 "content": "def transform(grid):
    """Extend each side of the solid 2-rectangle along its rows/columns.

    A nonzero marker outside the rectangle blocks extension on that side;
    the opposite side is handled independently. Original nonzero cells are kept.
    """
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    out = [row[:] for row in grid]

    # Extend each rectangle row toward an edge only when that ray is clear.
    for r in range(r0, r1 + 1):
        if all(grid[r][c] == 0 for c in range(0, c0)):
            for c in range(c0):
                if out[r][c] == 0:
                    out[r][c] = 2
        if all(grid[r][c] == 0 for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                if out[r][c] == 0:
                    out[r][c] = 2

    # Extend each rectangle column vertically, with the same independent rule.
    for c in range(c0, c1 + 1):
        if all(grid[r][c] == 0 for r in range(0, r0)):
            for r in range(r0):
                if out[r][c] == 0:
                    out[r][c] = 2
        if all(grid[r][c] == 0 for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
